 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let pos = 0;
+
+  while (pos < template.length) {
+    const tagStart = template.indexOf("{{", pos);
+    if (tagStart === -1) {
+      tokens.push({ kind: "text", text: template.slice(pos) });
+      break;
+    }
+
+    if (tagStart > pos) {
+      tokens.push({ kind: "text", text: template.slice(pos, tagStart) });
+    }
+
+    const isRaw = template.startsWith("{{{", tagStart);
+    const openLen = isRaw ? 3 : 2;
+    const closeTag = isRaw ? "}}}" : "}}";
+    const tagEnd = template.indexOf(closeTag, tagStart + openLen);
+
+    if (tagEnd === -1) throw new Error("unterminated tag");
+
+    const inner = template.slice(tagStart + openLen, tagEnd).trim();
+
+    if (isRaw) {
+      tokens.push({ kind: "value", expr: inner, raw: true });
+    } else if (inner.startsWith("#if ")) {
+      tokens.push({ kind: "if", path: inner.slice(4).trim() });
+    } else if (inner === "else") {
+      tokens.push({ kind: "else" });
+    } else if (inner === "/if") {
+      tokens.push({ kind: "end" });
+    } else {
+      tokens.push({ kind: "value", expr: inner, raw: false });
+    }
+
+    pos = tagEnd + closeTag.length;
+  }
+
+  return tokens;
 }
